responsePreview:
This Terraform configuration creates an AWS RDS PostgreSQL database instance whose master password is managed automatically by AWS Secrets Manager. It also creates a customer-managed AWS KMS key and configures the RDS-managed master user secret to be encrypted with that specific KMS key. The database is deployed into the default VPC using its existing subnets, with a security group allowing PostgreSQL access from within the default VPC.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where resources will be created."
  type        = string
  default     = "us-east-1"
}

variable "db_identifier" {
  description = "Identifier for the RDS database instance."
  type        = string
  default     = "managed-master-password-db"
}

variable "db_name" {
  description = "Initial database name."
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "Master username for the RDS database."
  type        = string
  default     = "dbadmin"
}

